-- Five M1 candidate-only revisions; no independent judgments or runtime bindings.
BEGIN;
DO $five$
DECLARE item jsonb; code text; v1 lf_ops.nucleo_regla_versiones%ROWTYPE;
 p jsonb; dry jsonb; wr jsonb; ev jsonb; sample jsonb; fact jsonb; newtests jsonb;
 oldtests jsonb; oldjudges jsonb; oldlegacy jsonb; oldrules jsonb; oldversions jsonb;
 oldapps jsonb; olddeprec jsonb; oldekb_count integer; h2 text; v_e jsonb; v_m jsonb;
 n integer; i integer:=0; total_tests integer:=0; ekb_code text;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY codigo) INTO oldrules FROM lf_ops.nucleo_reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO oldversions FROM lf_ops.nucleo_regla_versiones t
  WHERE t.regla NOT IN('M1-C01','M1-C02','M1-C04','M1-C05','M1-C06');
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones t;
 SELECT count(*) INTO oldekb_count FROM public.lf_error_knowledge;
 FOR item IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"M1-C01","hash_v1":"22770091e74a044db408f3ae19c2e56df9c4ea4140c2663d3fbe65e52a969a2c","motivo_revision":"Verificar unicidad y detalle real; selección sola era insuficiente","patch":{"titulo":"Bloquear resumen incompleto o no único","descripcion":"En presentación del resumen checkout, BLOQUEAR su aceptación si falta UNA consolidación, faltan detalles por oferta/modalidad o la selección no coincide. Indicadores lógicos sin binding real de Paulo; no calcula comisiones ni precio final (M1-D01).","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_resumen_checkout_en_presentacion"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"m1_resumen_checkout_corresponde_seleccion"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"m1_resumen_checkout_unico_verificado"},"der":{"lit":false}}},"der":{"op":"=","izq":{"hecho":"m1_resumen_checkout_detalle_por_oferta_modalidad_completo"},"der":{"lit":false}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":true,"m1_resumen_checkout_unico_verificado":false,"m1_resumen_checkout_detalle_por_oferta_modalidad_completo":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":true,"m1_resumen_checkout_unico_verificado":true,"m1_resumen_checkout_detalle_por_oferta_modalidad_completo":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":false,"m1_resumen_checkout_unico_verificado":true,"m1_resumen_checkout_detalle_por_oferta_modalidad_completo":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":true,"m1_resumen_checkout_unico_verificado":true,"m1_resumen_checkout_detall