  code:=item->>'codigo';
  SELECT * INTO STRICT v1 FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=1 AND estado='CANDIDATA';
  IF v1.hash IS DISTINCT FROM item->>'hash_v1'
    OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo=code)<>'CANDIDATA'
    OR (SELECT regla_legacy_id FROM lf_ops.nucleo_reglas WHERE codigo=code) IS NOT NULL
  THEN RAISE EXCEPTION 'M1_FIVE_BASE_HASH_OR_STATE_DRIFT %',code; END IF;
  SELECT jsonb_agg(to_jsonb(t) ORDER BY t.n) INTO oldtests FROM lf_ops.nucleo_regla_pruebas t WHERE t.regla=code AND version=1;
  SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO oldjudges FROM lf_ops.nucleo_juicios t WHERE t.regla=code AND version=1;
  FOR fact IN SELECT value FROM jsonb_array_elements(item->'nuevo_hechos') LOOP
   IF EXISTS (SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo=fact->>'codigo')
   THEN RAISE EXCEPTION 'M1_FIVE_FACT_COLLISION %',fact->>'codigo'; END IF;
   INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion)
   VALUES(fact->>'codigo',fact->>'tipo_dato',fact->>'unidad',fact->>'descripcion');
   INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen)
   SELECT n.familia,fact->>'codigo','CURADO' FROM lf_ops.nucleo_reglas n WHERE n.codigo=code;
  END LOOP;
  p:=v1.ficha || (item->'patch') || jsonb_build_object('tipo','REVISION','version_anterior',1,
    'hash_anterior',v1.hash,'motivo_revision',item->>'motivo_revision');
  IF p->'origen' IS DISTINCT FROM v1.origen OR p->>'autoridad' IS DISTINCT FROM v1.autoridad
    OR p->>'codigo' IS DISTINCT FROM code OR p->>'alcance' IS DISTINCT FROM v1.ficha->>'alcance'
  THEN RAISE EXCEPTION 'M1_FIVE_AUTHORITY_SCOPE_DRIFT %',code; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0
  THEN RAISE EXCEPTION 'M1_FIVE_PREFLIGHT_REJECTED % %',code,dry; END IF;
  n:=0;
  FOR sample IN SELECT value FROM jsonb_array_elements(p->'pruebas') LOOP
   v_e:=lf_ops.nucleo_eval_v1(p->'condicion',sample->'entrada');
   IF v_e IS DISTINCT FROM sample->'esperado'
   THEN RAISE EXCEPTION 'M1_FIVE_TEST_FAIL % % actual=% expected=%',code,n,v_e,sample->'esperado'; END IF;
   n:=n+1;
  END LOOP;
  IF n<5 THEN RAISE EXCEPTION 'M1_FIVE_LOW_COVERAGE %',code; END IF;
  total_tests:=total_tests+n;
  SELECT value INTO sample FROM jsonb_array_elements(p->'pruebas') WITH ORDINALITY t(value,ord)
   WHERE ord=(item->>'caso_mutante')::integer+1;
  v_m:=lf_ops.nucleo_eval_v1(item->'mutante',sample->'entrada');
  IF v_m IS NOT DISTINCT FROM sample->'esperado'
  THEN RAISE EXCEPTION 'M1_FIVE_SEMANTIC_MUTANT_SURVIVED % %',code,v_m; END IF;
  RAISE NOTICE 'M1_FIVE_CASES % %/% mutant_caught=%',code,n,n,v_m;
  wr:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF wr->>'resultado'<>'CANDIDATA' OR wr->>'version'<>'2'
  THEN RAISE EXCEPTION 'M1_FIVE_REVISION_REJECTED % %',code,wr; END IF;
  SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY t.n)
   INTO newtests FROM lf_ops.nucleo_regla_pruebas WHERE regla=code AND version=2;
  IF newtests IS DISTINCT FROM p->'pruebas'
    OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=1)<>'DESCARTADA'
    OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2)<>'CANDIDATA'
    OR (SELECT publicada_desde FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2) IS NOT NULL
    OR (SELECT exigible_desde FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2) IS NOT NULL
    OR (SELECT to_jsonb(t)-'estado' FROM lf_ops.nucleo_regla_versiones t WHERE t.regla=code AND t.version=1)
       IS DISTINCT FROM to_jsonb(v1)-'estado'
    OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY t.n) FROM lf_ops.nucleo_regla_pruebas t WHERE t.regla=code AND version=1) IS DISTINCT FROM oldtests
    OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.nucleo_juicios t WHERE t.regla=code AND version=1) IS DISTINCT FROM oldjudges
  THEN RAISE EXCEPTION 'M1_FIVE_HISTORY_OR_TESTS_DRIFT %',code; END IF;
  h2:=lf_ops.nucleo_hash_paquete_v1(code,2);
  IF h2 IS NULL OR h2=lf_ops.nucleo_hash_paquete_v1(code,1)
  THEN RAISE EXCEPTION 'M1_FIVE_VERSION_HASH_COLLISION %',code; END IF;
  ev:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF ev->>'decision' NOT IN('BLOQUEADA','DEVUELTA')
    OR EXISTS(SELECT 1 FROM lf_ops.nucleo_juicios j WHERE j.regla=code AND version=2)
  THEN RAISE EXCEPTION 'M1_FIVE_FALSE_AUTO % %',code,ev; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(dry->'controles') v WHERE v->>'n'='0'
   AND v->>'detalle'='REVISION_VERSION_OBSOLETA' AND v->>'ok'='false')
  THEN RAISE EXCEPTION 'M1_FIVE_STALE_REPLAY_ACCEPTED % %',code,dry; END IF;
  ekb_code:='LF-NUCLEO-'||code||'-SEMANTIC-GUARD-20261123-001';
  IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo=ekb_code)
  THEN RAISE EXCEPTION 'M1_FIVE_EKB_ALREADY_EXISTS %',code; END IF;
  INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,
    validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia)
  VALUES(ekb_code,'NUCLEO_REGLAS','Hallazgo semántico '||code,item->>'motivo_revision',
    'Condición V1 incompleta según juez en contexto actual','M1_V1_SEMANTIC_GAP',
    'V2 por puerta con prueba negativa específica y control hash; hechos lógicos no acreditan runtime Paulo.',
    'PG17 BEGIN/ROLLBACK, casos positivos/negativos y mutante; juicio independiente no ejecutado.',
    'HIGH',1,now(),now(),'M1-FIVE-V2-20261123','ACTIVO','sandbox/lf_contract_gate_test/nucleo_ci/m1_5_revisiones_v2.json#'||code);
  IF (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo=ekb_code)<>1
  THEN RAISE EXCEPTION 'M1_FIVE_EKB_WRITE_FAILURE %',code; END IF;
  RAISE NOTICE 'M1_FIVE_V2_RESULT %',jsonb_build_object('codigo',code,'hash',h2,'decision',ev->>'decision','tests',n,'estado','CANDIDATA');
  i:=i+1;
 END LOOP;
 IF i<>5 OR total_tests<>31 OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb_count+5
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM oldlegacy
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY codigo) FROM lf_ops.nucleo_reglas t) IS DISTINCT FROM oldrules
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones t WHERE t.regla NOT IN('M1-C01','M1-C02','M1-C04','M1-C05','M1-C06')) IS DISTINCT FROM oldversions
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones t) IS DISTINCT FROM oldapps
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM olddeprec
   OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_007')<>'CANDIDATA'
   OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla='M1-C03' AND version=2)<>'CANDIDATA'
 THEN RAISE EXCEPTION 'M1_FIVE_FINAL_READBACK_DRIFT % tests=%',i,total_tests; END IF;
 RAISE NOTICE 'M1_FIVE_V2_PASS 5/5 revisions, 31/31 tests, 5 mutants, 5 EKB; 0 published; legadas intactas';
END $five$;
COMMIT;
